      }
    }
  },
  "volumeSplit": {
    "chest": 37.5,
    "back": 39.1,
    "legs": 23.4
  },
  "strengthIndex": {
    "chest": {
      "currentIndex": 105,
      "previousIndex": 100
    },
    "back": {
      "currentIndex": 100,
      "previousIndex": 100
    },
